"""User lookups."""
import sqlite3


def connect(path):
    return sqlite3.connect(path)


def find_user(conn, name):
    """Return the row for the user called `name`, or None."""
    query = "SELECT id, name, email FROM users WHERE name = '" + name + "'"
    return conn.execute(query).fetchone()
